1	// shiftbook —— 本地多资源预约命令行工具
2	// 运行环境：Node.js 24（直接执行 TypeScript，无外部运行依赖）
3	//
4	// 时间一律使用与机器时区无关的营业地时间：
5	//   日期时间 YYYY-MM-DDTHH:mm，查询日期 YYYY-MM-DD
6	// 内部统一换算为“自公元 1 年起的分钟数”做比较，杜绝时区影响。
7	// 区间左闭右开 [start, end)，允许跨日。
8	//
9	// 预约系列：create-series 按周（每 7 个营业地日历日）生成多项预约，
10	// 全部成员使用相同资源；成员记录与普通预约同表，带 seriesId 归属。
11	//
12	// 候补队列：add-waitlist 登记“固定时段 + 多资源”的候补，
13	// add-flex-waitlist 登记“弹性窗口 + 所需连续时长 + 多资源”的候补（不占用资源，
14	// 登记时窗口内共同实际可用时间能容纳完整时长即可，忽略预约占用）；两种候补共用
15	// 同一条登记顺序，process-waitlist 按登记顺序手动处理整个队列（弹性项取窗口内
16	// 最早可行开始），为可兑现项各创建一项普通预约，受阻项继续等待且不影响后续项。
17	//
18	// iCalendar 导入：import-ical 读取本地 UTF-8 的 VCALENDAR（VERSION:2.0），
19	// 为每个新 VEVENT 创建预约（统一使用命令行给定的资源集合，不自动处理候补）：
20	// 无 RRULE 的独立事件创建一项普通预约；带 RRULE:FREQ=WEEKLY;COUNT=n 的事件创建
21	// 一个按周重复系列（EXDATE 排除的发生不生成成员）。UID 永久关联首次导入（独立
22	// 事件关联其预约；重复事件关联其系列、各原发生时间与对应成员），相同 UID 且
23	// 重复与否、首项时间、COUNT、排除集合与资源集合一致为重放（不改动原安排），
24	// 任一不同则整批拒绝。
25	//
26	// 多项预约目标（系列成员、批量改期目标、撤销恢复安排、导入新事件）的可行性
27	// 校验统一由 validateBatchTargets 完成（无写入副作用），各入口只负责展开
28	// 目标、给出需排除的当前占用，并按各自业务定位与顺序渲染诊断。
29	//
30	// 多进程写入保护：所有修改入口以同一数据文件为单位互斥（锁文件），保护覆盖
31	// 读取决策所需状态、业务校验、分配标识与原子保存全过程；取得保护后据最新数据
32	// 决策。相对/绝对/含 ./.. 的等价路径共享同一把锁，不同数据文件互不影响。
33	// 竞争可等待，5 秒内未取得即以退出码 1 报告占用；进程异常退出留下的残留保护
34	// 由 recover-lock 在确认原写入进程已退出后解除。查询不取锁，保存为原子替换，
35	// 只读到提交前或提交后的完整快照。
36	
37	import {lstat, readFile, writeFile, rename, unlink} from 'node:fs/promises';
38	import {realpathSync} from 'node:fs';
39	import {hostname} from 'node:os';
40	import {basename, dirname, join, resolve} from 'node:path';
41	import {createHash} from 'node:crypto';
