237	// ---------------------------------------------------------------------------
238	// 数据模型与文件存取
239	// ---------------------------------------------------------------------------
240	
241	type ResourceType = 'venue' | 'equipment' | 'person';
242	type BookingStatus = 'active' | 'cancelled';
243	type WaitlistStatus = 'waiting' | 'fulfilled' | 'cancelled';
244	type WaitlistKind = 'fixed' | 'flexible'; // 固定时段候补 / 弹性时段候补
245	type ClosureStatus = 'active' | 'cancelled';
246	type BatchOpStatus = 'active' | 'undone'; // 批量改期操作：未撤销 / 已撤销
247	
248	interface ResourceRec {
249	  id: string;
250	  type: ResourceType;
251	  name: string;
252	  open: Array<[string, string]>;
253	}
254	
255	interface BookingRec {
256	  id: string;
257	  resourceIds: string[];
258	  start: string;
259	  end: string;
260	  status: BookingStatus;
261	  seriesId?: string;
262	}
263	
264	interface SeriesRec {
265	  id: string;
266	}
267	
268	interface WaitlistRec {
269	  id: string; // 候补标识 W0001…，稳定且不复用
270	  kind: WaitlistKind; // fixed=固定时段；flexible=弹性时段（窗口内寻找最早连续时长）
271	  resourceIds: string[]; // 原请求资源（按标识排序）
272	  start: string; // 原请求开始时间；弹性项为窗口开始
273	  end: string; // 原请求结束时间；弹性项为窗口结束
274	  durationMinutes?: number; // 仅弹性项：所需连续时长（正整数分钟，不超过窗口长度）
275	  status: WaitlistStatus;
276	  seq: number; // 登记序号：1 基，列表与处理均按此稳定排序，重启后仍在
277	  bookingId?: string; // 已兑现时关联的普通预约标识
278	}
279	
280	interface ClosureRec {
281	  id: string; // 停用标识 C0001…，稳定且不复用
282	  resourceId: string; // 单个已登记资源
283	  start: string;
284	  end: string;
285	  status: ClosureStatus;
286	}
287	
288	// 一次批量改期提交中的单项快照（按清单顺序）
289	interface BatchOpItem {
290	  bookingId: string;
291	  seriesId?: string; // 提交时的系列归属（无系列则不含）
292	  before: {start: string; end: string; resourceIds: string[]}; // 改期前安排
293	  after: {start: string; end: string; resourceIds: string[]}; // 改期后安排（提交目标）
294	}
295	
296	interface BatchOpRec {
297	  id: string; // 批量改期操作标识 O0001…，稳定且不复用（即使记录已撤销）
298	  status: BatchOpStatus;
299	  items: BatchOpItem[]; // 按提交（清单）顺序
300	}
301	
302	// 一次 iCalendar 导入建立的“UID -> 预约/系列”永久关联：
303	// 独立事件（无 RRULE）：bookingId 指向首次导入生成的普通预约，count/exdates 缺省。
304	// 按周重复事件（RRULE:FREQ=WEEKLY;COUNT=n）：seriesId 指向首次导入创建的系列，
305	// occurrences 按原发生顺序记录每个未排除发生的原开始时间（YYYY-MM-DDTHH:mm）与
306	// 对应成员预约标识（排除的发生不在其中）；count/exdates 为首次请求的重复参数。
307	// 快照保留首次导入的时间与资源集合（之后成员被改期/取消、系列被整体取消也不变），
308	// 重放按快照比对本次请求，身份不依赖导入文件路径
309	interface ImportRec {
310	  uid: string; // 解码后的 UID（区分大小写），同一数据文件内唯一
311	  bookingId?: string; // 独立事件：首次导入生成的预约标识
312	  seriesId?: string; // 重复事件：首次导入创建的系列标识
313	  start: string; // 首次导入的开始时间快照（首项 DTSTART）YYYY-MM-DDTHH:mm
314	  end: string; // 首次导入的结束时间快照（首项 DTEND）
315	  resourceIds: string[]; // 首次导入的资源集合快照（按标识排序）
316	  count?: number; // 仅重复事件：RRULE COUNT（1..100000，含首项）
317	  exdates?: string[]; // 仅重复事件：排除集合快照（原开始时间文本，按时间排序去重）
318	  occurrences?: Array<{start: string; bookingId: string}>; // 仅重复事件：原发生时间 -> 成员
319	}
320	
321	interface Store {
322	  version: 1;
323	  resourceSeq: number;
324	  bookingSeq: number;
325	  seriesSeq: number;
326	  waitlistSeq: number; // 已分配的最大候补序号（计数不复用）
327	  closureSeq: number; // 已分配的最大停用序号（计数不复用）
328	  batchSeq: number; // 已分配的最大批量改期操作序号（计数不复用，撤销也不回收）
329	  resources: ResourceRec[];
330	  bookings: BookingRec[];
331	  series: SeriesRec[];
332	  waitlist: WaitlistRec[];
333	  closures: ClosureRec[];
334	  batchOps: BatchOpRec[];
335	  imports: ImportRec[];
336	}
