344	const RESOURCE_TYPE_MAP: Record<string, ResourceType> = {
345	  venue: 'venue',
346	  equipment: 'equipment',
347	  person: 'person',
348	  '场地': 'venue',
349	  '设备': 'equipment',
350	  '人员': 'person',
351	};
