353	function emptyStore(): Store {
354	  return {
355	    version: 1,
356	    resourceSeq: 0,
357	    bookingSeq: 0,
358	    seriesSeq: 0,
359	    waitlistSeq: 0,
360	    closureSeq: 0,
361	    batchSeq: 0,
362	    resources: [],
363	    bookings: [],
364	    series: [],
365	    waitlist: [],
366	    closures: [],
367	    batchOps: [],
368	    imports: [],
369	  };
370	}
