372	function isInt(v: unknown): v is number {
373	  return typeof v === 'number' && Number.isInteger(v) && v >= 0;
374	}
375	
376	// 严格校验数据文件结构；非法时抛出 BizError，调用方不得写回文件
377	function validateStore(raw: unknown, file: string): Store {
378	  const bad = (reason: string): never => {
379	    throw new BizError(`数据文件 ${file} 结构非法：${reason}（原文件已保留，未做修改）`);
380	  };
381	  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) bad('顶层必须是对象');
382	  const o = raw as Record<string, unknown>;
383	
384	  if (o.version !== undefined && o.version !== 1) bad(`不支持的版本: ${String(o.version)}`);
385	
386	  const store = emptyStore();
387	  if (o.resourceSeq !== undefined) {
388	    if (!isInt(o.resourceSeq)) bad('resourceSeq 必须是非负整数');
389	    store.resourceSeq = o.resourceSeq;
390	  }
391	  if (o.bookingSeq !== undefined) {
392	    if (!isInt(o.bookingSeq)) bad('bookingSeq 必须是非负整数');
393	    store.bookingSeq = o.bookingSeq;
394	  }
395	  if (o.seriesSeq !== undefined) {
396	    if (!isInt(o.seriesSeq)) bad('seriesSeq 必须是非负整数');
397	    store.seriesSeq = o.seriesSeq;
398	  }
399	  if (o.waitlistSeq !== undefined) {
400	    if (!isInt(o.waitlistSeq)) bad('waitlistSeq 必须是非负整数');
401	    store.waitlistSeq = o.waitlistSeq;
402	  }
403	  if (o.closureSeq !== undefined) {
404	    if (!isInt(o.closureSeq)) bad('closureSeq 必须是非负整数');
405	    store.closureSeq = o.closureSeq;
406	  }
407	  if (o.batchSeq !== undefined) {
408	    if (!isInt(o.batchSeq)) bad('batchSeq 必须是非负整数');
409	    store.batchSeq = o.batchSeq;
410	  }
411	
412	  if (o.resources !== undefined && !Array.isArray(o.resources)) bad('resources 必须是数组');
413	  if (o.bookings !== undefined && !Array.isArray(o.bookings)) bad('bookings 必须是数组');
