801	  //   独立事件 -> bookingId 指向一项普通预约；
802	  //   按周重复事件 -> seriesId 指向一个系列，occurrences 按原发生顺序记录每个
803	  //   未排除发生的原开始时间与对应成员（count/exdates 为首次请求的重复参数）。
804	  // 成员预约与系列均不得被另一条导入记录重复关联；快照自身须合法（真实时间、
805	  // 结束晚于开始、资源已知且不重复、COUNT 合法、排除集合与发生映射自洽）。
806	  // 成员现状（被改期/取消）与首次请求不同不算损坏。
807	  const importUids = new Set<string>();
808	  const importLinkedBookings = new Set<string>();
809	  const importLinkedSeries = new Set<string>();
810	  const claimBooking = (uid: string, bId: string, at: string): void => {
811	    if (!bookingById.has(bId)) bad(`${at}(UID “${uid}”) 关联了未知预约: ${bId}`);
812	    if (importLinkedBookings.has(bId)) {
813	      bad(`${at}(UID “${uid}”) 预约 ${bId} 已被另一条导入记录关联（一项预约只能对应一个 UID）`);
814	    }
815	    importLinkedBookings.add(bId);
816	  };
817	  rawImports.forEach((item, idx) => {
818	    const at = `imports[${idx}]`;
819	    if (typeof item !== 'object' || item === null || Array.isArray(item)) bad(`${at} 必须是对象`);
820	    const im = item as Record<string, unknown>;
821	    if (typeof im.uid !== 'string' || im.uid === '') bad(`${at}.uid 必须是非空字符串`);
822	    if (importUids.has(im.uid)) bad(`导入记录 UID 重复: ${im.uid}`);
823	    importUids.add(im.uid);
824	    const uid = im.uid;
825	
826	    const hasBooking = im.bookingId !== undefined;
827	    const hasSeries = im.seriesId !== undefined;
828	    if (hasBooking === hasSeries) {
829	      bad(`${at}(UID “${uid}”) 必须恰好提供 bookingId（独立事件）或 seriesId（重复事件）之一`);
830	    }
831	    if (typeof im.start !== 'string' || typeof im.end !== 'string') {
832	      bad(`${at}(UID “${uid}”) 快照起止时间必须是字符串`);
833	    }
834	    const s = parseDateTime(im.start as string, `${at}(UID “${uid}”).start`);
835	    const e = parseDateTime(im.end as string, `${at}(UID “${uid}”).end`);
836	    if (e <= s) bad(`${at}(UID “${uid}”) 快照结束必须晚于开始`);
837	    if (!Array.isArray(im.resourceIds) || im.resourceIds.length === 0) {
838	      bad(`${at}(UID “${uid}”).resourceIds 必须是非空数组`);
839	    }
840	    const rids = im.resourceIds as unknown[];
841	    const rseen = new Set<string>();
842	    rids.forEach((rid) => {
843	      if (typeof rid !== 'string' || !resourceIds.has(rid)) {
844	        bad(`${at}(UID “${uid}”) 快照引用了未知资源: ${String(rid)}`);
845	      }
846	      if (rseen.has(rid)) bad(`${at}(UID “${uid}”) 快照资源重复: ${rid}`);
847	      rseen.add(rid);
848	    });
849	
850	    const rec: ImportRec = {
851	      uid,
852	      start: im.start as string,
853	      end: im.end as string,
854	      resourceIds: [...rseen].sort(),
855	    };
856	
857	    if (hasBooking) {
858	      // 独立事件身份：不得携带重复字段
859	      if (typeof im.bookingId !== 'string' || !/^B\d{4,}$/.test(im.bookingId)) {
860	        bad(`${at}(UID “${uid}”).bookingId 非法: ${String(im.bookingId)}`);
861	      }
862	      for (const k of ['count', 'exdates', 'occurrences']) {
863	        if (im[k] !== undefined) bad(`${at}(UID “${uid}”) 独立事件身份不应携带 ${k}`);
864	      }
865	      claimBooking(uid, im.bookingId as string, at);
866	      rec.bookingId = im.bookingId as string;
867	      store.imports.push(rec);
868	      return;
869	    }
870	
871	    // 重复事件身份
872	    if (typeof im.seriesId !== 'string' || !/^S\d{4,}$/.test(im.seriesId)) {
873	      bad(`${at}(UID “${uid}”).seriesId 非法: ${String(im.seriesId)}`);
874	    }
875	    if (!seriesIds.has(im.seriesId)) {
876	      bad(`${at}(UID “${uid}”) 关联了未知系列: ${im.seriesId}`);
877	    }
878	    if (importLinkedSeries.has(im.seriesId)) {
879	      bad(`${at}(UID “${uid}”) 系列 ${im.seriesId} 已被另一条导入记录关联（一个系列只能对应一个 UID）`);
880	    }
881	    importLinkedSeries.add(im.seriesId);
882	    rec.seriesId = im.seriesId;
883	
884	    if (!isInt(im.count) || im.count < 1 || im.count > MAX_OCCURRENCES) {
885	      bad(`${at}(UID “${uid}”).count 必须是 1..${MAX_OCCURRENCES} 的整数`);
886	    }
887	    rec.count = im.count;
888	    if (!Array.isArray(im.exdates)) bad(`${at}(UID “${uid}”).exdates 必须是数组`);
889	    const exSet = new Set<string>();
890	    (im.exdates as unknown[]).forEach((xv, j) => {
891	      if (typeof xv !== 'string') bad(`${at}(UID “${uid}”).exdates[${j}] 必须是时间字符串`);
892	      parseDateTime(xv, `${at}(UID “${uid}”).exdates[${j}]`);
893	      if (exSet.has(xv)) bad(`${at}(UID “${uid}”) 排除时间重复: ${xv}`);
894	      exSet.add(xv);
895	    });
896	    rec.exdates = [...exSet].sort();
897	
898	    if (!Array.isArray(im.occurrences) || im.occurrences.length === 0) {
899	      bad(`${at}(UID “${uid}”).occurrences 必须是非空数组（全部发生被排除的首次请求非法）`);
900	    }
901	    const occTimes = new Set<string>();
902	    const occs: Array<{start: string; bookingId: string}> = [];
903	    (im.occurrences as unknown[]).forEach((ov, j) => {
904	      const oat = `${at}(UID “${uid}”).occurrences[${j}]`;
905	      if (typeof ov !== 'object' || ov === null || Array.isArray(ov)) bad(`${oat} 必须是对象`);
906	      const o = ov as Record<string, unknown>;
907	      for (const k of Object.keys(o)) {
908	        if (k !== 'start' && k !== 'bookingId') bad(`${oat} 存在未知字段 “${k}”`);
909	      }
910	      if (typeof o.start !== 'string') bad(`${oat}.start 必须是时间字符串`);
911	      parseDateTime(o.start, `${oat}.start`);
912	      if (occTimes.has(o.start)) bad(`${at}(UID “${uid}”) 原发生时间重复: ${o.start}`);
913	      occTimes.add(o.start);
914	      if (typeof o.bookingId !== 'string' || !/^B\d{4,}$/.test(o.bookingId)) {
915	        bad(`${oat}.bookingId 非法: ${String(o.bookingId)}`);
916	      }
917	      claimBooking(uid, o.bookingId, at);
918	      occs.push({start: o.start, bookingId: o.bookingId});
919	    });
920	
921	    // 映射自洽性：按首项与 COUNT 展开全部原发生（须在四位年份内），
922	    // 未排除发生必须恰好等于 occurrences（时间集合一致、顺序按发生先后）
923	    const expectedAll: string[] = [];
924	    for (let i = 0; i < rec.count; i++) {
925	      const raw = formatDateTime(s + i * 7 * 1440);
926	      if (raw === null) bad(`${at}(UID “${uid}”) 重复展开超出四位年份范围（0001-9999）`);
927	      expectedAll.push(raw);
928	    }
929	    const expectedKept = expectedAll.filter((t) => !exSet.has(t));
930	    const excludedNotInSeries = [...exSet].filter((t) => !expectedAll.includes(t));
931	    if (excludedNotInSeries.length > 0) {
932	      bad(`${at}(UID “${uid}”) 排除时间不匹配任何原发生: ${excludedNotInSeries.join('、')}`);
933	    }
934	    if (occs.length !== expectedKept.length || occs.some((o, j) => o.start !== expectedKept[j])) {
935	      bad(
936	        `${at}(UID “${uid}”) 发生映射缺漏或重复：COUNT=${rec.count}、排除 ${exSet.size} 项` +
937	          `时应有 ${expectedKept.length} 个未排除发生且按发生顺序排列`,
938	      );
939	    }
940	    // 成员必须恰好为所关联系列的全部成员（1:1：系列成员不重不漏）
941	    const seriesMembers = new Set(
942	      store.bookings.filter((b) => b.seriesId === rec.seriesId).map((b) => b.id),
943	    );
944	    for (const o of occs) {
945	      if (!seriesMembers.has(o.bookingId)) {
946	        bad(`${at}(UID “${uid}”) 成员 ${o.bookingId} 不属于系列 ${rec.seriesId}`);
947	      }
948	    }
949	    if (occs.length !== seriesMembers.size) {
950	      bad(`${at}(UID “${uid}”) 系列 ${rec.seriesId} 存在未登记在 occurrences 中的成员（系列与发生映射必须一一对应）`);
951	    }
952	    rec.occurrences = occs;
953	    store.imports.push(rec);
954	  });
955	
956	  store.resources.sort((a, b) => a.id.localeCompare(b.id));
957	  store.bookings.sort((a, b) => a.id.localeCompare(b.id));
958	  store.series.sort((a, b) => a.id.localeCompare(b.id));
959	  store.waitlist.sort((a, b) => a.seq - b.seq || a.id.localeCompare(b.id));
960	  store.closures.sort((a, b) => a.id.localeCompare(b.id));
961	  store.batchOps.sort((a, b) => Number(a.id.slice(1)) - Number(b.id.slice(1)));
962	  store.imports.sort((a, b) => a.uid.localeCompare(b.uid));
963	  return store;
964	}
