985	// 先完整写入临时文件，再原子改名；任何失败都不触碰原文件
986	async function saveStore(file: string, store: Store): Promise<void> {
987	  let json: string;
988	  try {
989	    json = JSON.stringify(store, null, 2) + '\n';
990	  } catch (err) {
991	    throw new BizError(`序列化数据失败：${(err as Error).message}（原文件已保留）`);
992	  }
993	  const tmp = `${file}.${process.pid}.tmp`;
994	  try {
995	    await writeFile(tmp, json, {encoding: 'utf8', flag: 'wx'});
996	    await rename(tmp, file);
997	  } catch (err) {
998	    await unlink(tmp).catch(() => {});
999	    throw new BizError(`保存数据文件 ${file} 失败：${(err as Error).message}（原文件已保留）`);
1000	  }
1001	}
