1003	// ---------------------------------------------------------------------------
1004	// 多进程写入保护（同一数据文件全局互斥）
1005	//
1006	// 所有修改入口在读取数据前先取得本数据文件的写入保护（锁文件，wx 独占创建），
1007	// 保护覆盖读取决策所需状态、业务校验、标识分配与原子保存全过程，命令结束时
1008	// 统一释放（正常结束、校验失败、保存失败均释放）。锁文件按数据文件的规范路径
1009	// 命名：相对路径、绝对路径与含 ./.. 的等价写法共享同一把锁；不同数据文件
1010	// 互不影响；数据文件尚不存在时同样受保护。竞争可等待，但 5 秒内未取得即以
1011	// 退出码 1 报告占用（可重试）。进程异常退出会留下残留锁：recover-lock 仅在
1012	// 确认原写入进程已退出后解除，存活或无法确认一律拒绝，不按保护存在时长抢占；
1013	// 释放与恢复都只删除自己确认的那一份，绝不误删其他进程后来取得的保护。
1014	// ---------------------------------------------------------------------------
1015	
1016	const LOCK_TIMEOUT_MS = 5000; // 取得写入保护的最长等待时间
1017	const LOCK_RETRY_MS = 40; // 竞争重试间隔（含随机抖动，避免齐步）
1018	
1019	// 数据文件的规范路径：解析相对路径与 ./..，并尽量解析符号链接
1020	// （文件尚不存在时解析其父目录，父目录也不可用时退化为绝对路径）
1021	function canonicalDataPath(file: string): string {
1022	  const abs = resolve(file);
1023	  try {
1024	    return realpathSync(abs);
1025	  } catch {
1026	    try {
1027	      return join(realpathSync(dirname(abs)), basename(abs));
1028	    } catch {
1029	      return abs;
1030	    }
1031	  }
1032	}
1033	
1034	// 锁文件路径：与数据文件同目录、按规范路径命名；文件名长度受限（如 255 字节）
1035	// 时退化为同目录下的散列锁名，同一数据文件的所有进程仍共享同一把锁
1036	function lockPathFor(file: string): string {
1037	  const canonical = canonicalDataPath(file);
1038	  const primary = `${canonical}.lock`;
1039	  if (Buffer.byteLength(basename(primary), 'utf8') <= 250) return primary;
1040	  const hash = createHash('sha256').update(canonical).digest('hex').slice(0, 24);
1041	  return join(dirname(canonical), `.shiftbook-${hash}.lock`);
1042	}
