1044	interface LockInfo {
1045	  pid: number; // 取得保护的进程
1046	  host: string; // 取得保护的主机（恢复时只能确认本机进程）
1047	  dataFile: string; // 被保护数据文件的规范路径
1048	  acquiredAt: string; // 取得时间（ISO 文本，仅供诊断，不作为解除依据）
1049	}
1050	
1051	function currentLockInfo(file: string): LockInfo {
1052	  return {
1053	    pid: process.pid,
1054	    host: hostname(),
1055	    dataFile: canonicalDataPath(file),
1056	    acquiredAt: new Date().toISOString(),
1057	  };
1058	}
