1060	// 本进程当前持有的锁（一次命令至多一把；main 统一释放）
1061	let heldLockPath: string | null = null;
1062	
1063	async function acquireWriteLock(file: string): Promise<void> {
1064	  if (heldLockPath !== null) return;
1065	  const lockPath = lockPathFor(file);
1066	  const content = JSON.stringify(currentLockInfo(file)) + '\n';
1067	  const deadline = Date.now() + LOCK_TIMEOUT_MS;
1068	  for (;;) {
1069	    try {
1070	      await writeFile(lockPath, content, {encoding: 'utf8', flag: 'wx'});
1071	      heldLockPath = lockPath;
1072	      return;
1073	    } catch (err) {
1074	      if ((err as NodeJS.ErrnoException).code !== 'EEXIST') {
1075	        throw new BizError(`无法取得数据文件写入保护（锁文件 ${lockPath}）：${(err as Error).message}`);
1076	      }
1077	      if (Date.now() >= deadline) {
1078	        let owner = '';
1079	        try {
1080	          const info = JSON.parse(await readFile(lockPath, 'utf8')) as LockInfo;
1081	          owner = `（当前由进程 ${info.pid} 持有，始于 ${info.acquiredAt}）`;
1082	        } catch {
1083	          // 占用信息不可读不影响“被占用”的结论
1084	        }
1085	        throw new BizError(
1086	          `数据文件 ${file} 正被其他进程占用${owner}：${LOCK_TIMEOUT_MS / 1000} 秒内未能取得写入保护，` +
1087	            '本次未做任何改动，可稍后重试；若确认原写入进程已异常退出，可使用 recover-lock 解除残留保护',
1088	        );
1089	      }
1090	      await new Promise((r) => setTimeout(r, LOCK_RETRY_MS + Math.floor(Math.random() * LOCK_RETRY_MS)));
1091	    }
1092	  }
1093	}
