1095	// 释放本进程取得的保护；仅删除自己创建的锁文件，绝不动其他进程后来取得的保护
1096	async function releaseWriteLock(): Promise<void> {
1097	  const lockPath = heldLockPath;
1098	  if (lockPath === null) return;
1099	  heldLockPath = null;
1100	  try {
1101	    const info = JSON.parse(await readFile(lockPath, 'utf8')) as LockInfo;
1102	    if (info.pid !== process.pid || info.host !== hostname()) return;
1103	    await unlink(lockPath);
1104	  } catch {
1105	    // 锁文件已不存在或不可读：不影响本次命令的结果
1106	  }
1107	}
