1116	// 本地恢复入口：仅确认原写入进程已退出时才解除残留保护；存活或无法确认一律
1117	// 明确拒绝，不按保护存在时长抢占。不重放旧命令，不改业务数据或标识计数。
1118	async function cmdRecoverLock(args: string[]): Promise<void> {
1119	  const {values, positionals} = parseFlags(args, []);
1120	  if (values.size > 0) {
1121	    throw new UsageError(`recover-lock 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`);
1122	  }
1123	  if (positionals.length > 0) {
1124	    throw new UsageError('用法: recover-lock（确认原写入进程已退出后，解除本数据文件的残留写入保护）');
1125	  }
1126	
1127	  const file = activeDataFile;
1128	  const lockPath = lockPathFor(file);
1129	  const readLock = async (): Promise<{dev: number; ino: number; text: string}> => {
1130	    const st = await lstat(lockPath);
1131	    return {dev: st.dev, ino: st.ino, text: await readFile(lockPath, 'utf8')};
1132	  };
1133	
1134	  let first: {dev: number; ino: number; text: string};
1135	  try {
1136	    first = await readLock();
1137	  } catch (err) {
1138	    if ((err as NodeJS.ErrnoException).code === 'ENOENT') {
1139	      console.log(`数据文件 ${file} 没有残留写入保护，无需恢复。`);
1140	      return;
1141	    }
1142	    throw new BizError(`无法读取写入保护文件 ${lockPath}: ${(err as Error).message}`);
1143	  }
1144	
1145	  let info: LockInfo;
1146	  try {
1147	    const parsed = JSON.parse(first.text) as LockInfo;
1148	    if (!Number.isInteger(parsed.pid) || parsed.pid <= 0 || typeof parsed.host !== 'string') {
1149	      throw new Error('invalid lock content');
1150	    }
1151	    info = parsed;
1152	  } catch {
1153	    throw new BizError(
1154	      `写入保护文件 ${lockPath} 内容无法辨认，无法确认原写入进程，拒绝解除（请人工核查后自行处理该文件）`,
1155	    );
1156	  }
1157	
1158	  if (info.host !== hostname()) {
1159	    throw new BizError(
1160	      `写入保护由另一台主机（${info.host}）的进程 ${info.pid} 取得，本机无法确认其是否已退出，拒绝解除`,
1161	    );
1162	  }
1163	
1164	  let alive = false;
1165	  try {
1166	    process.kill(info.pid, 0);
1167	    alive = true;
1168	  } catch (err) {
1169	    if ((err as NodeJS.ErrnoException).code !== 'ESRCH') {
1170	      throw new BizError(`无法确认原写入进程 ${info.pid} 是否已退出（无权限查询），拒绝解除写入保护`);
1171	    }
1172	  }
1173	  if (alive) {
1174	    throw new BizError(
1175	      `写入保护仍由运行中的进程 ${info.pid} 持有（始于 ${info.acquiredAt}），拒绝解除；` +
1176	        '不按保护存在时长抢占，请等待其结束，或确认其已退出后重试',
1177	    );
1178	  }
1179	
1180	  // 删除前再次核对：锁文件未被替换（inode 与内容均一致），
1181	  // 绝不误删其他进程在核对期间重新取得的保护
1182	  let second: {dev: number; ino: number; text: string};
1183	  try {
1184	    second = await readLock();
1185	  } catch (err) {
1186	    if ((err as NodeJS.ErrnoException).code === 'ENOENT') {
1187	      console.log('残留写入保护已被解除（可能由另一恢复入口处理），无需重复操作。');
1188	      return;
1189	    }
1190	    throw new BizError(`无法读取写入保护文件 ${lockPath}: ${(err as Error).message}`);
1191	  }
1192	  if (second.dev !== first.dev || second.ino !== first.ino || second.text !== first.text) {
1193	    throw new BizError('写入保护在核对期间已变化（可能已有新的写入者取得保护），拒绝解除');
1194	  }
1195	  await unlink(lockPath);
1196	  console.log(
1197	    `已解除数据文件 ${file} 的残留写入保护（原写入进程 ${info.pid} 已确认退出）。` +
1198	      '未重放任何旧命令，数据文件、业务记录与标识计数均未改动。',
1199	  );
1200	}
