1206	function formatResourceIds(store: Store, ids: string[]): string {
1207	  return ids
1208	    .map((id) => {
1209	      const r = store.resources.find((x) => x.id === id);
1210	      return r ? `${id}（${r.name}）` : id;
1211	    })
1212	    .join('、');
