1215	// 校验请求中的资源标识：去重、检查存在性；返回按标识排序的集合
1216	function resolveResourceIds(store: Store, rawIds: string[]): string[] {
1217	  const problems: string[] = [];
1218	  const seen = new Set<string>();
1219	  const dupes: string[] = [];
1220	  for (const id of rawIds) {
1221	    if (seen.has(id)) {
1222	      if (!dupes.includes(id)) dupes.push(id);
1223	    }
1224	    seen.add(id);
1225	  }
1226	  if (dupes.length > 0) problems.push(`资源重复指定: ${dupes.join('、')}`);
1227	
1228	  const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
1229	  if (unknown.length > 0) problems.push(`未知资源标识: ${unknown.join('、')}`);
1230	
1231	  if (problems.length > 0) throw new BizError(problems.join('\n'));
1232	  return [...seen].sort();
1233	}
