1235	function openSegmentsOf(r: ResourceRec): Array<[number, number]> {
1236	  return mergeIntervals(
1237	    r.open.map(
1238	      ([s, e]) =>
1239	        [parseDateTime(s, '开放区间开始时间'), parseDateTime(e, '开放区间结束时间')] as [number, number],
1240	    ),
1241	  );
1242	}
