1244	// 从连续区间中扣除一段停用（左闭右开），返回剩余连续区间
1245	function subtractSegments(
1246	  segments: Array<[number, number]>,
1247	  cuts: Array<[number, number]>,
1248	): Array<[number, number]> {
1249	  let result = segments;
1250	  for (const [cs, ce] of mergeIntervals(cuts)) {
1251	    const next: Array<[number, number]> = [];
1252	    for (const [s, e] of result) {
1253	      if (ce <= s || e <= cs) {
1254	        next.push([s, e]);
1255	        continue;
1256	      }
1257	      if (s < cs) next.push([s, cs]);
1258	      if (ce < e) next.push([ce, e]);
1259	    }
1260	    result = next;
1261	  }
1262	  return result;
1263	}
1264	
1265	// 某资源的有效停用记录（按开始时间、标识排序）
1266	function activeClosuresOf(store: Store, resourceId: string): ClosureRec[] {
1267	  return store.closures
1268	    .filter((c) => c.resourceId === resourceId && c.status === 'active')
1269	    .sort(
1270	      (a, b) =>
1271	        parseDateTime(a.start, '停用开始时间') - parseDateTime(b.start, '停用开始时间') ||
1272	        a.id.localeCompare(b.id),
1273	    );
1274	}
1275	
1276	// 实际可用时间：原开放区间合并后，扣除该资源全部有效停用区间的并集（原开放记录保留）
1277	function availableSegmentsOf(store: Store, r: ResourceRec): Array<[number, number]> {
1278	  const cuts = activeClosuresOf(store, r.id).map(
1279	    (c) =>
1280	      [parseDateTime(c.start, '停用开始时间'), parseDateTime(c.end, '停用结束时间')] as [number, number],
1281	  );
1282	  return subtractSegments(openSegmentsOf(r), cuts);
1283	}
