1291	// 找出实际可用时间（开放扣除有效停用）不能完整覆盖 [startMin, endMin) 的资源
1292	function findCoverageGaps(
1293	  store: Store,
1294	  ids: string[],
1295	  startMin: number,
1296	  endMin: number,
1297	): CoverageGap[] {
1298	  const gaps: CoverageGap[] = [];
1299	  for (const id of ids) {
1300	    const r = store.resources.find((x) => x.id === id)!;
1301	    if (isFullyCovered(availableSegmentsOf(store, r), startMin, endMin)) continue;
1302	    const closures = activeClosuresOf(store, id).filter((c) => {
1303	      const cs = parseDateTime(c.start, '停用开始时间');
1304	      const ce = parseDateTime(c.end, '停用结束时间');
1305	      return cs < endMin && startMin < ce;
1306	    });
1307	    gaps.push({id, r, closures});
1308	  }
1309	  return gaps;
1310	}
