1312	// 开放不足资源的统一展示：资源行 + 相关有效停用（标识与时间）
1313	function gapLines(gaps: CoverageGap[], indent: string): string[] {
1314	  const lines: string[] = [];
1315	  for (const g of gaps) {
1316	    lines.push(`${indent}- ${g.id}（${g.r.name}）`);
1317	    for (const c of g.closures) {
1318	      lines.push(`${indent}  相关有效停用: ${c.id}（${c.start} → ${c.end}）`);
1319	    }
1320	  }
1321	  return lines;
1322	}
