1335	interface Conflict {
1336	  booking: BookingRec;
1337	  shared: string[];
1338	}
1339	
1340	// 与“已预约”记录求冲突：共同资源且时间重叠（左闭右开）；可排除自身
1341	function findConflicts(
1342	  store: Store,
1343	  ids: string[],
1344	  startMin: number,
1345	  endMin: number,
1346	  excludeBookingId?: string,
1347	): Conflict[] {
1348	  const wanted = new Set(ids);
1349	  const conflicts: Conflict[] = [];
1350	  for (const b of store.bookings) {
1351	    if (b.status !== 'active') continue;
1352	    if (excludeBookingId !== undefined && b.id === excludeBookingId) continue;
1353	    const bStart = parseDateTime(b.start, '预约开始时间');
1354	    const bEnd = parseDateTime(b.end, '预约结束时间');
1355	    const overlap = bStart < endMin && startMin < bEnd;
1356	    if (!overlap) continue;
1357	    const shared = b.resourceIds.filter((id) => wanted.has(id)).sort();
1358	    if (shared.length > 0) conflicts.push({booking: b, shared});
1359	  }
1360	  conflicts.sort((a, b) => a.booking.id.localeCompare(b.booking.id));
1361	  return conflicts;
1362	}
1363	
1364	function assertNoConflicts(conflicts: Conflict[], store: Store): void {
1365	  if (conflicts.length === 0) return;
1366	  const lines = conflicts.map(
1367	    (c) => `- ${c.booking.id}：共同资源 ${formatResourceIds(store, c.shared)}`,
1368	  );
1369	  throw new BizError(`预约与以下预约冲突（共同资源时间重叠）：\n${lines.join('\n')}`);
1370	}
