1439	function splitGlobalArgs(argv: string[]): GlobalArgs {
1440	  const result: GlobalArgs = {dataFile: DEFAULT_DATA_FILE, help: false, rest: []};
1441	  for (let i = 0; i < argv.length; i++) {
1442	    const a = argv[i];
1443	    if (a === '-h' || a === '--help') {
1444	      result.help = true;
1445	    } else if (a === '--data') {
1446	      const v = argv[++i];
1447	      if (v === undefined) throw new UsageError('选项 --data 缺少数据文件路径');
1448	      result.dataFile = v;
1449	    } else if (a.startsWith('--data=')) {
1450	      result.dataFile = a.slice('--data='.length);
1451	      if (result.dataFile === '') throw new UsageError('选项 --data 缺少数据文件路径');
1452	    } else {
1453	      result.rest.push(a);
1454	    }
1455	  }
1456	  return result;
1457	}
