1459	interface ParsedFlags {
1460	  values: Map<string, string[]>;
1461	  positionals: string[];
1462	}
1463	
1464	// 子命令选项解析：allowed 中列出的选项均需带值；multi 中的选项可重复
1465	function parseFlags(args: string[], allowed: string[], multi: string[] = []): ParsedFlags {
1466	  const allowedSet = new Set(allowed);
1467	  const multiSet = new Set(multi);
1468	  const values = new Map<string, string[]>();
1469	  const positionals: string[] = [];
1470	
1471	  const takeValue = (key: string, inline: string | undefined, index: number): [string, number] => {
1472	    if (inline !== undefined) return [inline, index];
1473	    const v = args[index + 1];
1474	    if (v === undefined || v.startsWith('-')) {
1475	      throw new UsageError(`选项 --${key} 缺少值`);
1476	    }
1477	    return [v, index + 1];
1478	  };
1479	
1480	  for (let i = 0; i < args.length; i++) {
1481	    const a = args[i];
1482	    if (a.startsWith('--')) {
1483	      let key: string;
1484	      let inline: string | undefined;
1485	      const eq = a.indexOf('=');
1486	      if (eq >= 0) {
1487	        key = a.slice(2, eq);
1488	        inline = a.slice(eq + 1);
1489	      } else {
1490	        key = a.slice(2);
1491	      }
1492	      if (!allowedSet.has(key)) throw new UsageError(`未知选项: --${key}`);
1493	      let v: string;
1494	      [v, i] = takeValue(key, inline, i);
1495	      if (v === '') throw new UsageError(`选项 --${key} 的值不能为空`);
1496	      if (!multiSet.has(key) && values.has(key)) {
1497	        throw new UsageError(`选项 --${key} 只能指定一次`);
1498	      }
1499	      const list = values.get(key) ?? [];
1500	      list.push(v);
1501	      values.set(key, list);
1502	    } else if (a.startsWith('-') && a !== '-') {
1503	      throw new UsageError(`未知参数: ${a}`);
1504	    } else {
1505	      positionals.push(a);
1506	    }
1507	  }
1508	  return {values, positionals};
1509	}
1510	
1511	function requireFlag(values: Map<string, string[]>, key: string): string {
1512	  const v = values.get(key)?.[0];
1513	  if (v === undefined) throw new UsageError(`缺少必需选项 --${key}`);
1514	  return v;
1515	}
