1634	  let ids: string[] = booking.resourceIds;
1635	  if (hasResource) {
1636	    const resourceArgs = values.get('resource')!;
1637	    ids = resolveResourceIds(store, resourceArgs);
1638	  }
1639	
1640	  assertOpenCoverage(store, ids, startMin, endMin);
1641	  // 改期检查排除自身
1642	  assertNoConflicts(findConflicts(store, ids, startMin, endMin, id), store);
1643	
1644	  // 全部可用后整体替换旧安排并落盘；失败则本进程内存与磁盘上的原安排都不变。
1645	  // seriesId 不随改期变化：改期后仍属原系列。

