2006	    );
2007	  }
2008	  if (positionals.length !== 1) {
2009	    throw new UsageError('用法: undo-batch-op <批量改期操作标识>');
2010	  }
2011	  const opId = positionals[0];
2012	  if (!/^O\d{4,}$/.test(opId)) throw new BizError(`批量改期操作标识非法: ${opId}`);
