2018	
2019	  if (op.status === 'undone') {
2020	    // 幂等：重复撤销已撤销记录成功且不触碰当前安排——即使之后又有改期
2021	    console.log(`操作 ${opId} 已是撤销状态，未做任何改动（当前安排保持不变）。`);
