2027	  // 任一不一致即整笔拒绝并列出全部不一致预约。
2028	  const mismatches: string[] = [];
2029	  const involved = new Map<string, {booking: BookingRec; item: BatchOpItem; index: number}>();
2030	  op.items.forEach((item, index) => {
2031	    const b = store.bookings.find((x) => x.id === item.bookingId);
