2050	    if (curSeries !== recSeries) {
2051	      reasons.push(
2052	        `当前系列归属 ${curSeries ?? '无'} 与记录的系列归属 ${recSeries ?? '无'} 不一致`,
2053	      );
2054	    }
2055	    if (reasons.length > 0) {
