2062	      `撤销 ${opId} 被拒绝：存在 ${mismatches.length} 项涉及预约的当前状态与该记录改期后安排不一致` +
2063	        '（整笔不变，未恢复任何安排、未改变记录状态）：\n' +
2064	        mismatches.map((m) => `- ${m}`).join('\n'),
2065	    );
2066	  }
2067	
2068	  // 可行性：对“整笔恢复后”的最终安排做统一批次校验（无写入副作用）。
2069	  // 本操作涉及预约的当前占用一律排除（允许互换时段）；
2070	  // 障碍只来自本操作之外的有效预约，以及各项恢复安排彼此之间。
2071	  const involvedIds = new Set(op.items.map((it) => it.bookingId));
