2073	    startMin: parseDateTime(item.before.start, '恢复开始时间'),
2074	    endMin: parseDateTime(item.before.end, '恢复结束时间'),
2075	    resourceIds: item.before.resourceIds,
2076	  }));
2077	  const failures = validateBatchTargets(store, targets, involvedIds);
2078	
2079	  if (failures.length > 0) {
2080	    // 按提交顺序报告全部失败项；批内冲突在双方项中都会出现
2081	    const blocks = failures.map((f) => {
2082	      const item = op.items[f.index];
2083	      const lines = [
2084	        `第 ${f.index + 1} 项 ${item.bookingId} 恢复为 ${item.before.start} → ${item.before.end}：`,
2085	      ];
2086	      if (f.gaps.length > 0) {
2087	        lines.push('  开放不足资源:');
2088	        lines.push(...gapLines(f.gaps, '    '));
2089	      }
2090	      if (f.external.length + f.internal.length > 0) {
2091	        lines.push('  冲突预约:');
2092	        for (const c of f.external) {
2093	          lines.push(
2094	            `    - ${c.booking.id}（${c.booking.start} → ${c.booking.end}）` +
2095	              `：共同资源 ${formatResourceIds(store, c.shared)}`,
2096	          );
2097	        }
2098	        for (const x of f.internal) {
2099	          const o = op.items[x.otherIndex];
2100	          lines.push(
2101	            `    - ${o.bookingId}（本操作第 ${x.otherIndex + 1} 项恢复为 ${o.before.start} → ${o.before.end}）` +
2102	              `：共同资源 ${formatResourceIds(store, x.shared)}`,
2103	          );
2104	        }
2105	      }
2106	      return lines.join('\n');
2107	    });
2108	    throw new BizError(
2109	      `撤销 ${opId} 失败：共 ${failures.length} 项恢复安排不满足条件（按提交顺序），整笔未改动：\n${blocks.join('\n')}`,
