2120	  }
2121	  op.status = 'undone';
2122	  await saveStore(file, store);
2123	
2124	  console.log(
2125	    `已安全撤销 ${opId}：共 ${op.items.length} 项恢复为改期前安排（标识、有效状态与系列归属不变，未新增记录、未改变标识计数）`,
2126	  );
2127	  op.items.forEach((item, i) => {
