2209	// 按周展开系列：每项相对前一项将起止时间同时后移 7 个营业地日历日，
2210	// 时刻与跨日长度保持不变。任何一项超出四位年份范围即整体拒绝。
2211	function planWeeklyMembers(startMin: number, endMin: number, count: number): PlannedMember[] {
2212	  const members: PlannedMember[] = [];
2213	  for (let i = 0; i < count; i++) {
2214	    const s = startMin + i * 7 * 1440;
2215	    const e = endMin + i * 7 * 1440;
2216	    const startRaw = formatDateTime(s);
2217	    const endRaw = formatDateTime(e);
2218	    if (startRaw === null || endRaw === null) {
