  }
  console.log(`预约系列（共 ${store.series.length} 个）：`);
  for (const s of store.series) {
    const members = store.bookings
      .filter((b) => b.seriesId === s.id)
      .map((b) => ({b, startMin: parseDateTime(b.start, '预约开始时间')}))
