11	import {test} from 'node:test';
12	import assert from 'node:assert/strict';
13	import {spawn, spawnSync, type ChildProcess} from 'node:child_process';
14	import {mkdtempSync, rmSync, writeFileSync, readFileSync, existsSync, readdirSync, realpathSync} from 'node:fs';
15	import {tmpdir, hostname} from 'node:os';
16	import {join, dirname, basename, resolve} from 'node:path';
17	import {fileURLToPath} from 'node:url';
18	
19	const APP = join(dirname(fileURLToPath(import.meta.url)), '..', 'app.ts');
20	const OPEN_ALL: Array<[string, string]> = [['2026-01-01T00:00', '2027-01-01T00:00']];
21	// 255 字节文件名：保存时临时文件（<名>.<pid>.tmp）必然超出文件名长度上限，
22	// 从而在不调整任何权限的前提下，可重复地触发真实保存失败。
23	const LONG_NAME = 'f'.repeat(250) + '.json';
24	
25	// ---------------------------------------------------------------------------
26	// 基础设施
27	// ---------------------------------------------------------------------------
28	
29	interface CliResult {
30	  status: number;
31	  stdout: string;
32	  stderr: string;
33	}
34	
35	function runCli(dataFile: string, args: string[]): CliResult {
36	  const r = spawnSync(process.execPath, [APP, '--data', dataFile, ...args], {encoding: 'utf8'});
37	  if (r.error) throw r.error;
38	  return {status: r.status ?? -1, stdout: r.stdout ?? '', stderr: r.stderr ?? ''};
39	}
40	
41	// 异步并发入口：真实并行子进程竞争同一数据文件
42	function runCliAsync(dataFile: string, args: string[], cwd?: string): Promise<CliResult> {
43	  return new Promise((resolveP, reject) => {
44	    const p = spawn(process.execPath, [APP, '--data', dataFile, ...args], {encoding: 'utf8', cwd});
45	    let stdout = '';
46	    let stderr = '';
47	    p.stdout.on('data', (d) => (stdout += d));
48	    p.stderr.on('data', (d) => (stderr += d));
49	    p.on('error', reject);
50	    p.on('close', (status) => resolveP({status: status ?? -1, stdout, stderr}));
51	  });
52	}
53	
54	function ok(df: string, args: string[], ctx: string): CliResult {
55	  const r = runCli(df, args);
56	  assert.equal(
57	    r.status,
58	    0,
59	    `[${ctx}] 期望退出 0，实际 ${r.status}\n命令: ${args.join(' ')}\nstderr:\n${r.stderr}\nstdout:\n${r.stdout}`,
60	  );
61	  return r;
62	}
63	
64	function tempDir(t: {after: (fn: () => void) => void}): string {
65	  const dir = mkdtempSync(join(tmpdir(), 'shiftbook-lock-test-'));
66	  t.after(() => rmSync(dir, {recursive: true, force: true}));
67	  return dir;
68	}
69	
70	function addResource(df: string, name: string, open: Array<[string, string]> = OPEN_ALL): void {
71	  const args = ['add-resource', '--type', 'venue', '--name', name];
72	  for (const [s, e] of open) args.push('--open', `${s}/${e}`);
73	  ok(df, args, `登记资源 ${name}`);
74	}
75	
76	function readStore(df: string): any {
77	  return JSON.parse(readFileSync(df, 'utf8'));
78	}
79	
80	// 与应用一致的锁文件路径：规范路径（解析相对/./..与符号链接）+ .lock
81	function lockPathOf(df: string, cwd?: string): string {
82	  const abs = resolve(cwd ?? process.cwd(), df);
83	  let canonical: string;
84	  try {
85	    canonical = realpathSync(abs);
86	  } catch {
87	    canonical = join(realpathSync(dirname(abs)), basename(abs));
88	  }
89	  return `${canonical}.lock`;
90	}
91	
92	// 用一个真实存活进程持有指定数据文件的写入保护；release 结束该进程并等待其退出
93	function holdLock(df: string, t: {after: (fn: () => void) => void}, cwd?: string): {
94	  child: ChildProcess;
95	  lockPath: string;
96	  release: () => Promise<void>;
97	} {
98	  const child = spawn(process.execPath, ['-e', 'setInterval(() => {}, 1000)'], {stdio: 'ignore'});
99	  const lockPath = lockPathOf(df, cwd);
100	  const info = {
101	    pid: child.pid,
102	    host: hostname(),
103	    dataFile: resolve(cwd ?? process.cwd(), df),
104	    acquiredAt: new Date().toISOString(),
105	  };
106	  writeFileSync(lockPath, JSON.stringify(info) + '\n', {encoding: 'utf8', flag: 'wx'});
107	  let released = false;
108	  const release = (): Promise<void> => {
109	    if (released) return Promise.resolve();
110	    released = true;
111	    return new Promise((resolveP) => {
112	      child.once('close', () => resolveP());
113	      try {
114	        child.kill('SIGKILL');
115	      } catch {
116	        resolveP();
117	      }
118	    });
119	  };
120	  t.after(() => {
121	    void release();
122	    rmSync(lockPath, {force: true});
123	  });
124	  return {child, lockPath, release};
125	}
126	
127	// 一个已经退出的进程标识（用于构造残留保护）
128	function deadPid(): Promise<number> {
129	  return new Promise((resolveP, reject) => {
130	    const child = spawn(process.execPath, ['-e', ''], {stdio: 'ignore'});
131	    child.on('error', reject);
132	    child.on('close', () => resolveP(child.pid!));
133	  });
134	}
135	
136	function leftoverLocks(dir: string): string[] {
137	  return readdirSync(dir).filter((n) => n.endsWith('.lock') || n.startsWith('.shiftbook-'));
138	}
