2610	// 返回裁剪到窗口内并合并后的占用区间。
2611	function flexBusySegments(
2612	  store: Store,
2613	  ids: string[],
2614	  wStart: number,
2615	  wEnd: number,
2616	): Array<[number, number]> {
2617	  const wanted = new Set(ids);
2618	  const cuts: Array<[number, number]> = [];
2619	  for (const b of store.bookings) {
2620	    if (b.status !== 'active') continue;
2621	    if (!b.resourceIds.some((id) => wanted.has(id))) continue;
2622	    const bStart = parseDateTime(b.start, '预约开始时间');
2623	    const bEnd = parseDateTime(b.end, '预约结束时间');
2624	    const a = Math.max(bStart, wStart);
2625	    const c = Math.min(bEnd, wEnd);
2626	    if (a < c) cuts.push([a, c]);
2627	  }
2628	  return mergeIntervals(cuts);
2629	}
