3011	// 解析 RRULE 值：仅支持 FREQ=WEEKLY 与 COUNT=n 两个部件（n 为 1..100000 的整数，
3012	// 含首项）；部件名大小写无关、顺序无关。空部件、重复部件、FREQ 其他取值、
3013	// INTERVAL/BYDAY/UNTIL 等任何其他部件一律拒绝。
3014	function parseWeeklyRrule(value: string, bad: (reason: string) => never): number {
3015	  const segs = value.split(';');
3016	  let freq: string | undefined;
3017	  let count: string | undefined;
3018	  for (const seg of segs) {
3019	    const eq = seg.indexOf('=');
3020	    if (eq <= 0) bad(`RRULE 部件格式非法: “${seg}”（应为 名称=值）`);
3021	    const name = seg.slice(0, eq).trim().toUpperCase();
3022	    const v = seg.slice(eq + 1).trim();
3023	    if (v === '') bad(`RRULE 部件 ${name} 的值不能为空`);
3024	    if (name === 'FREQ') {
3025	      if (freq !== undefined) bad('RRULE 的 FREQ 部件重复');
3026	      freq = v.toUpperCase();
3027	    } else if (name === 'COUNT') {
3028	      if (count !== undefined) bad('RRULE 的 COUNT 部件重复');
3029	      count = v;
3030	    } else {
3031	      bad(`不支持的 RRULE 部件 “${seg}”（仅支持 FREQ=WEEKLY 与 COUNT）`);
3032	    }
3033	  }
3034	  if (freq === undefined) bad('RRULE 缺少 FREQ 部件（仅支持 FREQ=WEEKLY）');
3035	  if (freq !== 'WEEKLY') bad(`仅支持按周重复 FREQ=WEEKLY，实际为 FREQ=${freq}`);
3036	  if (count === undefined) bad('RRULE 缺少 COUNT 部件（仅支持 FREQ=WEEKLY;COUNT=n）');
3037	  if (!/^\d+$/.test(count)) bad(`RRULE 的 COUNT 必须是整数: “${count}”`);
3038	  const n = Number(count);
3039	  if (n < 1 || n > MAX_OCCURRENCES) {
3040	    bad(`RRULE 的 COUNT 必须在 1..${MAX_OCCURRENCES} 之间（含首项）: “${count}”`);
3041	  }
3042	  return n;
