    const claimPath = join(dir, name);
    try {
      const recoverPid = Number(name.slice(prefix.length));
      if (!Number.isInteger(recoverPid) || recoverPid <= 0) {
        throw new BizError(`恢复交接文件 ${claimPath} 名称无法辨认，无法确认交接状态，拒绝继续（请人工核查）`);
